package org.sleepwell.app;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;
/** Additive evidence, separate from raw sensor and user edit tables. */
final class AwakeStore {
 static final Set<String> STATES=Set.of("off","active","complete","interrupted","error");static final Set<String> REASONS=Set.of("phone_use","bright_light","snooze");
 static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE awake_runs(session INTEGER PRIMARY KEY,policy TEXT NOT NULL,state TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 0)");db.execSQL("CREATE TABLE awake_estimates(id INTEGER PRIMARY KEY,session INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,reason TEXT NOT NULL,ignored INTEGER NOT NULL DEFAULT 0)");db.execSQL("CREATE INDEX awake_session ON awake_estimates(session,start)");}
 static void begin(Store store,long id,AwakePolicy policy,String error){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject s=session(store,id);if(!s.isNull("end")||!s.optString("source").equals("tracked")||!s.optString("health_connect","").isEmpty())throw new IllegalArgumentException("Awake estimates need the active phone recording.");ContentValues v=new ContentValues();v.put("session",id);v.put("policy",policy.encode());v.put("state",!error.isEmpty()?"error":policy.enabled?"active":"off");v.put("error",error);db.insertOrThrow("awake_runs",null,v);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 static JSONObject session(Store store,long id){List<JSONObject> rows=store.rows("SELECT * FROM sessions WHERE id=?",""+id);if(rows.size()!=1)throw new IllegalArgumentException("This recording no longer exists.");return rows.get(0);}
 static void append(Store store,long id,long from,long to,String reason){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject s=session(store,id);AwakeData run=read(store,id);AwakePolicy p=AwakePolicy.decode(run.policy);if(!run.state.equals("active")||!p.enabled||!REASONS.contains(reason)||reason.equals("phone_use")&&!p.interaction||reason.equals("bright_light")&&!p.light||reason.equals("snooze")&&!p.snooze||from<s.optLong("start")||to<=from||to-s.optLong("start")>AwakeEngine.MAX||!s.isNull("end")&&to>s.optLong("end")||store.rows("SELECT id FROM awake_estimates WHERE session=?",""+id).size()>=10000)throw new IllegalArgumentException("Invalid awake estimate interval.");ContentValues v=new ContentValues();v.put("session",id);v.put("start",from);v.put("end",to);v.put("reason",reason);db.insertOrThrow("awake_estimates",null,v);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 static void finish(Store store,long id,String state,String error){if(!STATES.contains(state)||state.equals("active")||error==null||error.length()>512)throw new IllegalArgumentException("Invalid awake outcome.");ContentValues v=new ContentValues();v.put("state",state);v.put("error",error);if(store.getWritableDatabase().update("awake_runs",v,"session=? AND state IN ('active','error')",new String[]{""+id})>0)store.surfaceChanged();}
 static void recover(SQLiteDatabase db,long id){db.execSQL("UPDATE awake_runs SET state='interrupted' WHERE session=? AND state='active'",new Object[]{id});}
 static AwakeData read(Store store,long id){List<JSONObject> runs=store.rows("SELECT * FROM awake_runs WHERE session=?",""+id);if(runs.isEmpty())return AwakeData.UNKNOWN;JSONObject run=runs.get(0);AwakePolicy.decode(run.optString("policy"));List<AwakeData.Event> events=new ArrayList<>();for(JSONObject e:store.rows("SELECT * FROM awake_estimates WHERE session=? ORDER BY start,id",""+id))events.add(new AwakeData.Event(e.optLong("id"),e.optLong("start"),e.optLong("end"),e.optString("reason"),e.optInt("ignored")!=0));return new AwakeData(run.optString("policy"),run.optString("state"),run.optString("error"),run.optLong("revision"),events);}
 static void review(Store store,long id,long event,long expected,boolean ignored){review(store,id,event,expected,Records.get(store,id).updated,ignored);}
 static void review(Store store,long id,long event,long expected,long editRevision,boolean ignored){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{RecordEntry record=Records.get(store,id);AwakeData run=read(store,id);if(record.updated!=editRevision||record.manual()||!record.healthConnect.isEmpty()||run.policy.isEmpty()||run.revision!=expected||expected==Long.MAX_VALUE||run.state.equals("active"))throw new IllegalArgumentException("The awake review changed. Reopen it first.");ContentValues changed=new ContentValues();changed.put("ignored",ignored?1:0);String where="session=?";String[] args={""+id};if(event>0){where+=" AND id=?";args=new String[]{""+id,""+event};}if(db.update("awake_estimates",changed,where,args)==0)throw new IllegalArgumentException("This awake estimate no longer exists.");db.execSQL("UPDATE awake_runs SET revision=revision+1 WHERE session=?",new Object[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();store.surfaceChanged();}}
 static void erase(SQLiteDatabase db){db.delete("awake_estimates",null,null);db.delete("awake_runs",null,null);}
}
